package com.zhs.controller;import com.zhs.common.NoLoginRequest;import com.zhs.common.Result;import com.zhs.common.TokenUtil;import com.zhs.common.UserContext;import com.zhs.exception.ServiceException;import com.zhs.request.auth.PhoneLoginReq;import com.zhs.request.auth.SendCodeReq;import com.zhs.request.auth.WxLoginReq;import com.zhs.response.auth.CurrentUserResp;import com.zhs.response.auth.PhoneLoginResp;import com.zhs.response.auth.WxLoginResp;import com.zhs.service.auth.AuthService;import com.zhs.service.dto.auth.LoginResult;import com.zhs.service.dto.auth.PhoneLoginCommand;import com.zhs.service.dto.auth.UserProfileDto;import com.zhs.service.dto.auth.WxLoginCommand;import jakarta.annotation.Resource;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import lombok.extern.slf4j.Slf4j;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;/** * 认证相关接口 — 登录 / 当前用户 / 退出 */@Slf4j@RestController@RequestMapping("/api/auth")public class AuthController {    @Resource    private AuthService authService;    @NoLoginRequest    @PostMapping("/wx-login")    public Result<WxLoginResp> wxLogin(@Valid @RequestBody WxLoginReq req) {        WxLoginCommand command = new WxLoginCommand();        command.setCode(req.getCode());        command.setNickname(req.getNickname());        command.setAvatar(req.getAvatar());        return Result.ok(toWxLoginResp(authService.wxLogin(command)));    }    @NoLoginRequest    @PostMapping("/send-code")    public Result<Void> sendCode(@Valid @RequestBody SendCodeReq req) {        authService.sendPhoneCode(req.getPhone());        return Result.ok();    }    @NoLoginRequest    @PostMapping("/phone-login")    public Result<PhoneLoginResp> phoneLogin(@Valid @RequestBody PhoneLoginReq req) {        PhoneLoginCommand command = new PhoneLoginCommand();        command.setPhone(req.getPhone());        command.setCode(req.getCode());        return Result.ok(toPhoneLoginResp(authService.phoneLogin(command)));    }    @PostMapping("/current-user")    public Result<CurrentUserResp> currentUser() {        Long userId = UserContext.getUserId();        if (userId == null) {            throw new ServiceException("未登录", 401);        }        return Result.ok(toCurrentUserResp(authService.getCurrentUser(userId)));    }    @PostMapping("/logout")    public Result<Void> logout(HttpServletRequest request) {        String token = TokenUtil.resolveFrom(request);        authService.logout(token);        return Result.ok();    }    private WxLoginResp toWxLoginResp(LoginResult result) {        WxLoginResp resp = new WxLoginResp();        resp.setToken(result.getToken());        resp.setUserId(result.getUserId());        resp.setNickname(result.getNickname());        resp.setAvatar(result.getAvatar());        return resp;    }    private PhoneLoginResp toPhoneLoginResp(LoginResult result) {        PhoneLoginResp resp = new PhoneLoginResp();        resp.setToken(result.getToken());        resp.setUserId(result.getUserId());        resp.setNickname(result.getNickname());        resp.setAvatar(result.getAvatar());        return resp;    }    private CurrentUserResp toCurrentUserResp(UserProfileDto dto) {        CurrentUserResp resp = new CurrentUserResp();        resp.setUserId(dto.getUserId());        resp.setNickname(dto.getNickname());        resp.setAvatar(dto.getAvatar());        return resp;    }}